/* ── THE PLANET, AS A PLATE ────────────────────────────────────────────────────────
   The map used to be a slippy map — tiles, panning, zoom, a library of its own. On a
   desktop that made the record look broken and, worse, dishonest: a Mercator frame cut
   the world off at ±85°, so Antarctica was not on it and the Arctic was a strip at the
   top edge. The one page whose whole job is to say *the whole planet* was showing a
   band of it, and leaving a grey panel beside it.

   So the world is drawn as a plate now: land and sea as a stipple of ink dots, on the
   record's own paper, in equirectangular projection. Every degree of latitude gets the
   same height, so the poles are present and in proportion — the Arctic at the top edge
   and Antarctica along the bottom, exactly where they are.

   The stipple is generated by script from Natural Earth's 1:110m land layer: public
   domain, made by the National Geographic Society and the US government, so the shape
   of the world on this page belongs to nobody and can never be invoiced or withdrawn.
   It was never drawn by hand and never produced by an image model, because a record of
   the world cannot carry a made-up coastline.

   It is also tiny — 1,200 characters for the entire planet — and it is one SVG path, so
   it cannot lag, cannot load a tile late, and looks identical on a phone and a desktop.
   120 columns × 60 rows over lon −180..180 and lat 90..−90. */
export const PLATE_W = 120;
export const PLATE_H = 60;

const MASK =
  '';

let cache = null;

// The land, as one path of round-capped zero-length segments. One node, no matter how
// big the screen: a dot is a stroke with a round cap, so the whole planet is a single
// path and the browser draws it once.
export function landDots() {
  if (cache) return cache;
  const bytes = typeof atob === 'function' ? atob(MASK) : '';
  const parts = [];
  for (let y = 0; y < PLATE_H; y++) {
    for (let x = 0; x < PLATE_W; x++) {
      const n = y * PLATE_W + x;
      const byte = bytes.charCodeAt(n >> 3);
      if (byte && (byte & (1 << (7 - (n & 7))))) parts.push(`M${x + 0.5} ${y + 0.5}h.01`);
    }
  }
  cache = parts.join('');
  return cache;
}

// Where a place sits on the plate, as a percentage of the frame. Read straight off the
// latitude and longitude — nothing is stored about a place beyond that.
export function projectPct(lat, lng) {
  const la = Math.max(-90, Math.min(90, Number(lat)));
  const ln = Math.max(-180, Math.min(180, Number(lng)));
  return { left: ((ln + 180) / 360) * 100, top: ((90 - la) / 180) * 100 };
}

// Marks in the same country are set apart a little, so the second entry in a place is
// not hidden under the first. Small, fixed, in pixels — a nudge, not a scatter.
export function nudge(index) {
  if (!index) return [0, 0];
  const i = index;
  const angle = (i * 137.5 * Math.PI) / 180;
  const radius = 9 + Math.sqrt(i) * 12;
  return [Math.cos(angle) * radius, Math.sin(angle) * radius];
}